#!/usr/bin/env python3
from pathlib import Path
import argparse,base64,collections,csv,hashlib,html,json,re,shutil,subprocess,urllib.parse
from PIL import Image,ImageDraw,ImageFont

def family(url):
 p=urllib.parse.urlsplit(url).path.removeprefix('/en');p=p or '/'
 if p=='/':return 'Inicio'
 if p=='/videos/':return 'Biblioteca de vídeos'
 if p.startswith('/videos/'):return 'Página de vídeo'
 if p.startswith('/visuales/'):return 'Hub visual'
 if p.startswith('/herramientas/'):return 'Herramientas'
 if p.startswith('/temas/'):return 'Conceptos'
 if p.startswith('/series/'):
  if '00_presentacion' in p:return 'Presentación de serie'
  return 'Series y capítulos'
 if p.startswith('/articulos-tecnicos/'):return 'Ingeniería'
 return 'Otros / navegación'

def main():
 ap=argparse.ArgumentParser();ap.add_argument('--coverage',type=Path,required=True);ap.add_argument('--output',type=Path,required=True);a=ap.parse_args();o=a.output;o.mkdir(exist_ok=True,parents=True)
 pages=json.loads((a.coverage/'pages.json').read_text());rendered=json.loads((a.coverage/'rendered.json').read_text());rm={r['url']:r for r in rendered};summary=json.loads((a.coverage/'summary.json').read_text());pilot=json.loads((o/'pilot-validation.json').read_text())
 policies={'Inicio':'Conservar layout editorial. Actualizar póster destacado y derivarlo del mismo render que el vídeo.','Biblioteca de vídeos':'Miniaturas extraídas del nuevo render; tipografía coherente; duración del archivo real; sin fondos decorativos por serie.','Página de vídeo':'Re-render del MP4, póster equivalente, marco sin sombra ni degradado; controles nativos y texto accesible.','Hub visual':'Unificar los vídeos destacados y los módulos interactivos; no quitar interactividad ni señales de datos.','Herramientas':'Mantener cálculos, unidades, leyendas y controles. Quitar decoración; conservar color únicamente si codifica una variable o estado.','Conceptos':'Eliminar fondos decorativos de los componentes visuales, conservar diagramas y explicaciones.','Presentación de serie':'Usar un esquema real de los capítulos o conceptos; eliminar glifos y marcos ornamentales.','Series y capítulos':'Actualizar embed, póster y animaciones compartidas. Mantener contenido y orden de lectura.','Ingeniería':'Conservar capturas reales de interfaz y trazas; portada editorial; no sustituir evidencia por ilustraciones.','Otros / navegación':'Conservar la base minimalista; evitar intervención sin un problema observado.'}
 inventory=[]
 for p in sorted(pages,key=lambda r:r['url']):
  r=rm.get(p['url'],{});g=r.get('desktop',{}).get('gradients',[]);vids=[urllib.parse.urljoin(p['url'],v['src']) for v in p.get('videos',[]) if v.get('src')]
  f=family(p['url']);inventory.append({'url':p['url'],'locale':'en' if '/en/' in p['url'] else 'es','family':f,'http_status':p.get('status'),'canonical':p.get('canonical'),'video_count':len(vids),'video_urls':vids,'gradient_count':len(g),'gradient_classes':sorted({str(x.get('cls','')) for x in g}),'desktop_ok':'desktop_error' not in r and 'desktop' in r,'mobile_ok':'mobile_error' not in r and 'mobile' in r,'mobile_overflow':r.get('mobile',{}).get('scrollWidth',0)>392,'action':policies[f]})
 (o/'inventario-paginas.json').write_text(json.dumps(inventory,ensure_ascii=False,indent=2))
 with (o/'inventario-paginas.csv').open('w',newline='',encoding='utf-8-sig') as f:
  writer=csv.DictWriter(f,fieldnames=inventory[0].keys());writer.writeheader()
  for row in inventory:writer.writerow({k:' | '.join(map(str,v)) if isinstance(v,list) else v for k,v in row.items()})
 # Probe each publicly referenced repository media asset; distinguish URLs from actual unique bytes.
 media=[];urls=sorted({u for row in inventory for u in row['video_urls']})
 for u in urls:
  p=urllib.parse.urlsplit(u).path
  local=Path('locales/en')/p.removeprefix('/en/') if p.startswith('/en/') else Path('docs')/p.lstrip('/')
  rec={'url':u,'source_file':str(local)}
  if local.exists():
   probe=json.loads(subprocess.check_output(['ffprobe','-v','error','-show_format','-show_streams','-of','json',str(local)]));rec.update(duration=float(probe['format']['duration']),sha256=hashlib.sha256(local.read_bytes()).hexdigest(),streams=[{'type':s['codec_type'],'codec':s['codec_name'],'width':s.get('width'),'height':s.get('height')} for s in probe['streams']])
  else:rec['error']='Public URL did not map to a tracked repository file'
  media.append(rec)
 (o/'inventario-videos.json').write_text(json.dumps(media,ensure_ascii=False,indent=2))
 family_counts=collections.Counter(row['family'] for row in inventory)
 summary.update(gradient_pages=sum(r['gradient_count']>0 for r in inventory),gradient_elements=sum(r['gradient_count'] for r in inventory),family_counts=dict(family_counts),unique_video_hashes=len({v['sha256'] for v in media if 'sha256' in v}),canonical_values=len({p.get('canonical') for p in pages if p.get('canonical')}),media_probe_errors=sum('error' in v for v in media))
 (o/'cobertura-validada.json').write_text(json.dumps(summary,ensure_ascii=False,indent=2))
 original=Path('docs/series/modelos-razonadores/03-test-time-compute.mp4');shutil.copy2(original,o/'5sigmas-test-time-compute-antes.mp4')
 subprocess.run(['ffmpeg','-hide_banner','-loglevel','error','-y','-ss','34','-i',str(original),'-frames:v','1',str(o/'antes-fotograma.png')],check=True)
 font=ImageFont.truetype('/usr/share/fonts/opentype/inter/Inter-Medium.otf',31)
 before=Image.open(o/'antes-fotograma.png').convert('RGB').resize((1440,810));after=Image.open(o/'escena-04.png').convert('RGB').resize((1440,810))
 plate=Image.new('RGB',(1440,1780),'white');d=ImageDraw.Draw(plate);d.text((26,19),'ANTES · fotograma real del vídeo publicado',font=font,fill='#111111');plate.paste(before,(0,70));d.text((26,914),'DESPUÉS · prototipo editorial con mecanismos explícitos',font=font,fill='#111111');plate.paste(after,(0,970));plate.save(o/'antes-despues.png')
 # Accessible, self-contained comparison. No network calls or bundled font files.
 def datafile(name,mime):return 'data:'+mime+';base64,'+base64.b64encode((o/name).read_bytes()).decode()
 scenes=pilot['scenes'];chapters=''.join(f'<button type="button" data-time="{t}">{i+1:02d} · {html.escape(s["kicker"].capitalize())}</button>' for i,(t,s) in enumerate(zip(pilot['scene_starts'],scenes)))
 comparison='''<!doctype html><html lang="es"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>5sigmas · antes / después</title><style>*{box-sizing:border-box}body{margin:0;background:#fff;color:#111;font:16px/1.55 system-ui,sans-serif}main{max-width:1320px;margin:auto;padding:32px 22px}header{display:flex;justify-content:space-between;gap:20px;border-bottom:1px solid #dedede;padding-bottom:15px}h1{font-size:clamp(32px,5vw,58px);line-height:1.07;letter-spacing:-.045em;font-weight:650;margin-bottom:18px}p{max-width:80ch}nav{display:flex;gap:8px;flex-wrap:wrap;margin:22px 0}button{font:inherit;background:white;border:1px solid #aaa;padding:9px 15px;cursor:pointer;color:#111}button[aria-pressed=true]{background:#111;color:white;border-color:#111}button:focus-visible,video:focus-visible{outline:3px solid #111;outline-offset:4px}video{width:100%;display:block;background:white;border:1px solid #dedede}video[hidden]{display:none}small,.muted{color:#666}#copy{max-width:75ch;border-top:1px solid #dedede;margin-top:26px;padding-top:10px}#chapters button{font-size:14px}a{color:inherit}body.dark{background:#111;color:#f5f5f5}body.dark .muted,body.dark small{color:#aaa}body.dark button{background:#111;color:#f5f5f5}body.dark button[aria-pressed=true]{background:#f5f5f5;color:#111}@media(max-width:600px){main{padding:20px 14px}header{font-size:14px}#chapters{display:grid;grid-template-columns:1fr 1fr}video{margin-left:0}#copy{font-size:18px}}</style><main><header><strong>5sigmas</strong><span>Prototipo de revisión · no publicado</span></header><h1>Test-Time Compute.<br>Antes y después.</h1><p>La misma estructura de siete escenas y seis explicaciones. Fondo plano, Inter y diagramas que muestran el mecanismo. Ambos archivos duran 71,37 segundos y no contienen pista de audio.</p><nav aria-label="Versión"><button id="before" aria-pressed="false">Antes</button><button id="after" aria-pressed="true">Después</button><button id="theme" aria-pressed="false">Entorno oscuro</button></nav><video id="v0" hidden controls playsinline preload="metadata" aria-label="Vídeo original"></video><video id="v1" controls playsinline preload="metadata" aria-label="Vídeo rediseñado"></video><p class="muted">Alterna entre versiones conservando el tiempo. En móvil, usa pantalla completa para el vídeo y el texto de la escena que aparece debajo. El botón de entorno oscuro cambia la página, no los píxeles del MP4.</p><nav id="chapters" aria-label="Ir a una escena">CHAPTERS</nav><section id="copy" aria-label="Texto accesible de la escena"><h2></h2><div></div></section><details><summary>Cambios de contenido separados del rediseño</summary><p>No se ha recortado la explicación: el texto principal pasa de 300 a 351 palabras. Se mantienen los siete títulos. Se corrige la serie de la portada, se distingue best-of-N de consenso y se compara o1 consigo mismo (74% → 83%), en lugar de atribuir al presupuesto una diferencia entre modelos. También se eliminan absolutos sobre búsqueda y latencia. Las fuentes y los cambios están documentados en el informe.</p></details><p><small>Auditoría: 18 de septiembre de 2026. El prototipo no sustituye ningún archivo de producción.</small></p></main><script>const scenes=SCENES,starts=STARTS;const vs=[document.getElementById('v0'),document.getElementById('v1')];vs[0].src='BEFORE_DATA';vs[1].src='AFTER_DATA';vs[1].poster='POSTER_DATA';let active=1;function showCopy(){let i=0;for(let j=0;j<starts.length;j++)if(vs[active].currentTime>=starts[j])i=j;document.querySelector('#copy h2').textContent=scenes[i].title;const el=document.querySelector('#copy div');el.replaceChildren(...scenes[i].paragraphs.map(s=>{const p=document.createElement('p');p.textContent=s;return p}));}function choose(n){if(n===active)return;const old=vs[active],time=old.currentTime,playing=!old.paused;old.pause();old.hidden=true;active=n;const next=vs[n];next.hidden=false;next.currentTime=time;document.getElementById('before').setAttribute('aria-pressed',n===0);document.getElementById('after').setAttribute('aria-pressed',n===1);if(playing)next.play().catch(()=>{});showCopy();}document.getElementById('before').onclick=()=>choose(0);document.getElementById('after').onclick=()=>choose(1);document.getElementById('theme').onclick=e=>{const on=document.body.classList.toggle('dark');e.target.setAttribute('aria-pressed',on)};document.querySelectorAll('[data-time]').forEach(b=>b.onclick=()=>{vs[active].currentTime=Number(b.dataset.time);showCopy()});vs.forEach(v=>v.addEventListener('timeupdate',showCopy));showCopy();</script></html>'''
 comparison=comparison.replace('CHAPTERS',chapters).replace('SCENES',json.dumps(scenes,ensure_ascii=False)).replace('STARTS',json.dumps(pilot['scene_starts'])).replace('BEFORE_DATA',datafile('5sigmas-test-time-compute-antes.mp4','video/mp4')).replace('AFTER_DATA',datafile('5sigmas-test-time-compute-despues.mp4','video/mp4')).replace('POSTER_DATA',datafile('poster-despues.jpg','image/jpeg'))
 (o/'comparador.html').write_text(comparison,encoding='utf-8')
 # Full page inventory remains machine-readable and visible in a searchable HTML table.
 table=''.join('<tr><td><a href="'+html.escape(r['url'])+'">'+html.escape(urllib.parse.urlsplit(r['url']).path)+'</a></td><td>'+r['family']+'</td><td>'+str(r['video_count'])+'</td><td>'+str(r['gradient_count'])+'</td><td>'+html.escape(r['action'])+'</td></tr>' for r in inventory)
 (o/'inventario-paginas.html').write_text('<!doctype html><html lang="es"><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>5sigmas · inventario auditado</title><style>body{font:15px/1.5 system-ui;color:#111;padding:24px}table{border-collapse:collapse;width:100%}td,th{border-bottom:1px solid #dedede;text-align:left;padding:12px;vertical-align:top}a{color:inherit;overflow-wrap:anywhere}input{font:inherit;padding:10px;width:min(100%,600px)}@media(max-width:700px){table{font-size:12px}td,th{padding:6px}}</style><h1>314 rutas · inventario completo</h1><p>Capturadas en escritorio (1440 × 1000) y móvil (390 × 844). Los degradados cuentan elementos CSS visibles, no píxeles del vídeo. Los valores no son una puntuación estética ni prueba de accesibilidad completa.</p><input id="q" aria-label="Filtrar páginas" placeholder="Filtrar por URL, familia o acción"><table><thead><tr><th>Ruta</th><th>Familia</th><th>Vídeos</th><th>Degradados CSS</th><th>Acción propuesta</th></tr></thead><tbody>'+table+'</tbody></table><script>document.getElementById("q").oninput=e=>document.querySelectorAll("tbody tr").forEach(r=>r.hidden=!r.textContent.toLowerCase().includes(e.target.value.toLowerCase()))</script></html>')
 shutil.copy2(Path(__file__).with_name('pilot.py'),o/'pilot.py');shutil.copy2(Path(__file__),o/'package_review.py')
 print('AUDIT_FINAL_SUMMARY '+json.dumps(summary,ensure_ascii=False));print('VIDEO_PROBES '+json.dumps([{'url':v['url'],'duration':v.get('duration'),'hash':v.get('sha256')} for v in media],ensure_ascii=False))
if __name__=='__main__':main()
